// ===== CONFIGURATION =====
const BOT_TOKEN = 'YOUR_BOT_TOKEN_HERE';
const CHANNEL_ID = '@SmartHomeIL_deals';
// =========================

// Load products from website
const data = $input.item.json;
if (!data || !data.products || data.products.length === 0) {
  throw new Error('Failed to load products. Check the products URL.');
}
const products = data.products;

// Rotation tracking via workflow static data
const staticData = $getWorkflowStaticData('global');
if (typeof staticData.currentIndex !== 'number') {
  staticData.currentIndex = 0;
}
if (!staticData.weeklyProducts) {
  staticData.weeklyProducts = [];
}

// Pick next product (sequential rotation)
const product = products[staticData.currentIndex % products.length];
staticData.currentIndex = (staticData.currentIndex + 1) % products.length;

// Track for weekly digest
staticData.weeklyProducts.push({
  name: product.name,
  hebrewName: product.hebrewName,
  priceDisplay: product.priceDisplay,
  buyLink: product.buyLink
});

// Build beautiful Hebrew deal message
const haLabels = {
  full: 'נתמך מלא ✅',
  partial: 'נתמך חלקית ⚠️',
  none: 'לא נתמך ❌'
};
const catEmoji = {
  switches: '💡',
  'ac-controllers': '❄️',
  sensors: '📡',
  hubs: '🔌',
  vacuums: '🧹',
  plugs: '🔌',
  cameras: '📷',
  lighting: '💡',
  covers: '🪟',
  climate: '🌡️',
  controllers: '🎮'
};
const emoji = catEmoji[product.category] || '📦';

const text = `🏠 <b>דיל בית חכם!</b>

${emoji} <b>${product.name}</b> - ${product.hebrewName}
💰 <b>${product.priceDisplay}</b>
⚡ מאומת 220V ישראלי ✅
🔌 פרוטוקול: ${product.protocol}
🏡 Home Assistant: ${haLabels[product.homeAssistantSupport]}
⭐ דירוג: ${product.rating}/5

✨ ${product.description}

🛒 <a href="${product.buyLink}">לרכישה ←</a>
📖 <a href="${product.websiteLink}">למדריך המלא באתר</a>

#בית_חכם #220V #SmartHomeIL`;

return [{ json: { botToken: BOT_TOKEN, channelId: CHANNEL_ID, text } }];

// ===== CONFIGURATION =====
const BOT_TOKEN = 'YOUR_BOT_TOKEN_HERE';
const CHANNEL_ID = '@SmartHomeIL_deals';
const WEBSITE_URL = 'https://ziv-daniel.github.io/smart-income/';
// =========================

const staticData = $getWorkflowStaticData('global');
const weeklyProducts = staticData.weeklyProducts || [];

// Skip if no products were posted this week
if (weeklyProducts.length === 0) {
  return [];
}

const productsList = weeklyProducts.map((p, i) =>
  `${i + 1}. <b>${p.name}</b> - ${p.hebrewName} (${p.priceDisplay})`
).join('\n');

const text = `📋 <b>סיכום שבועי — בית חכם IL</b>

השבוע סקרנו ${weeklyProducts.length} מוצרים מעולים:

${productsList}

🌐 <a href="${WEBSITE_URL}">לכל ההשוואות והמדריכים באתר</a>

💡 טיפ: הצטרפו לערוץ כדי לקבל 3 דילים חדשים כל יום!

#בית_חכם #סיכום_שבועי #SmartHomeIL`;

// Clear weekly tracking for next week
staticData.weeklyProducts = [];

return [{ json: { botToken: BOT_TOKEN, channelId: CHANNEL_ID, text } }];
